    missing = []
    for key in required_keys:
        if key not in config:
            missing.append(key)
    return missing

def summarize_results(results):
    summary = {'success': 0, 'failed': 0}
    for item in results:
        if item.get('returncode') == 0:
            summary['success'] += 1
        else:
            summary['failed'] += 1
    return summary

