class DeploymentChecker:
    def __init__(self):
        self._env = {}

    def load_env(self, env_string):
        for line in env_string.splitlines():
            line = line.strip()
            if not line or line.startswith('#'):
                continue
            if '=' in line:
                key, _, value = line.partition('=')
                self._env[key.strip()] = value.strip()
        return self._env

    def check_required_vars(self, required):
        return [var for var in required if var not in self._env]

    def validate_port(self, port_str):
        try:
            port = int(port_str)
            if 1 <= port <= 65535:
                return [True, port]
            return [False, None]
        except (TypeError, ValueError):
            return [False, None]

    def generate_report(self, service, required):
        missing = self.check_required_vars(required)
        port_ok, _ = self.validate_port(self._env.get('PORT', ''))
        ok = len(missing) == 0 and port_ok
        return {'service': service, 'missing': missing, 'port_valid': port_ok, 'ok': ok}
